CREATE VIEW vw_preference_seed_calibration_normalized AS WITH margin_distribution AS (SELECT preference_margin FROM vw_game_preference_margin WHERE (preference_margin IS NOT NULL)), distribution_size AS (SELECT count_star() AS game_count FROM margin_distribution)SELECT c.PreferenceSeedID, c.PreferenceTier, c.ConditionalFlag, c.GameID, c.GameTitle, c.explicit_preference_score, n.explicit_preference_percentile, c.loo_preference_margin, CASE  WHEN ((c.loo_preference_margin IS NULL)) THEN (NULL) ELSE round(((100.0 * (SELECT count_star() FROM margin_distribution AS md WHERE (md.preference_margin <= c.loo_preference_margin))) / ds.game_count), 2) END AS loo_similarity_percentile, c.playability_adjustment FROM vw_preference_seed_calibration AS c LEFT JOIN vw_recommendation_normalized AS n ON ((n.GameID = c.GameID)) , distribution_size AS ds;
